struct OwnerTruthMemoryFacetValue: Equatable, Sendable {
    let value: String
    let evidenceMode: OwnerTruthFacetEvidenceMode
    let confidence: Double
    fileprivate let rawObject: [String: OwnerTruthJSONValue]

    fileprivate init?(jsonValue: OwnerTruthJSONValue) {
        guard case .object(let object) = jsonValue,
              case .string(let rawValue)? = object["value"],
              case .string(let rawEvidenceMode)? = object["evidenceMode"],
              let evidenceMode = OwnerTruthFacetEvidenceMode(rawValue: rawEvidenceMode),
              case .number(let confidence)? = object["confidence"],
              confidence.isFinite,
              (0...1).contains(confidence) else {
            return nil
        }
        let value = rawValue.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !value.isEmpty else { return nil }
        self.value = value
        self.evidenceMode = evidenceMode
        self.confidence = confidence
        rawObject = object
    }

    fileprivate func ownerCorrectedJSONValue(value: String) -> OwnerTruthJSONValue {
        var object = rawObject
        object["value"] = .string(value)
        object["evidenceMode"] = .string(OwnerTruthFacetEvidenceMode.ownerStated.rawValue)
        object["confidence"] = .number(1.0)
        return .object(object)
    }
}

struct OwnerTruthMemoryFacets: Equatable, Sendable {
    let valuesByKind: [OwnerTruthMemoryFacetKind: [OwnerTruthMemoryFacetValue]]
    let confidence: Double
    private let rawObject: [String: OwnerTruthJSONValue]

    init?(
        jsonValue: OwnerTruthJSONValue,
        requiredKinds: [OwnerTruthMemoryFacetKind] = OwnerTruthMemoryFacetKind.allCases
    ) {
        guard case .object(let object) = jsonValue,
              case .number(let confidence)? = object["confidence"],
              confidence.isFinite,
              (0...1).contains(confidence) else {
            return nil
        }
        var valuesByKind: [OwnerTruthMemoryFacetKind: [OwnerTruthMemoryFacetValue]] = [:]
        for kind in OwnerTruthMemoryFacetKind.allCases {
            guard let rawValues = object[kind.rawValue] else {
                // V2/V3 payloads predate the four extended V4 facets. Treat a
                // missing extended array as "not extracted", while malformed
                // values that are present still fail closed.
                guard !requiredKinds.contains(kind) else { return nil }
                valuesByKind[kind] = []
                continue
            }
            guard case .array(let values) = rawValues else {
                return nil
            }
            var parsed: [OwnerTruthMemoryFacetValue] = []
            parsed.reserveCapacity(values.count)
            for value in values {
                guard let item = OwnerTruthMemoryFacetValue(jsonValue: value) else {
                    return nil
                }
                parsed.append(item)
            }
            valuesByKind[kind] = parsed
        }
        self.valuesByKind = valuesByKind
        self.confidence = confidence
        rawObject = object
    }

    func values(for kind: OwnerTruthMemoryFacetKind) -> [OwnerTruthMemoryFacetValue] {
        valuesByKind[kind] ?? []
    }

    var isEmpty: Bool {
        OwnerTruthMemoryFacetKind.allCases.allSatisfy { values(for: $0).isEmpty }
    }

    /// Rebuilds only known facet arrays. Unknown provider fields remain in the
    /// raw object, while every value explicitly submitted by the Owner becomes
    /// owner-stated evidence.
    func ownerCorrectedJSONValue(
        valuesByKind correctedValues: [OwnerTruthMemoryFacetKind: [String]],
        markOverallOwnerConfirmed: Bool = true
    ) -> OwnerTruthJSONValue {
        var object = rawObject
        for (kind, submittedValues) in correctedValues {
            var currentValues: [String: OwnerTruthMemoryFacetValue] = [:]
            for value in values(for: kind) {
                currentValues[Self.comparisonKey(value.value)] = value
            }
            var seen: Set<String> = []
            let normalizedValues = submittedValues.compactMap { rawValue -> String? in
                let value = rawValue.trimmingCharacters(in: .whitespacesAndNewlines)
                let key = Self.comparisonKey(value)
                guard !value.isEmpty, seen.insert(key).inserted else { return nil }
                return value
            }
            object[kind.rawValue] = .array(normalizedValues.map { value in
                let existing = currentValues[Self.comparisonKey(value)]
                return existing?.ownerCorrectedJSONValue(value: value)
                    ?? .object([
                        "value": .string(value),
                        "evidenceMode": .string(OwnerTruthFacetEvidenceMode.ownerStated.rawValue),
                        "confidence": .number(1.0),
                    ])
            })
        }
        if markOverallOwnerConfirmed {
            object["confidence"] = .number(1.0)
        }
        return .object(object)
    }

    private static func comparisonKey(_ value: String) -> String {
        value.folding(options: [.caseInsensitive, .widthInsensitive], locale: .current)
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
    }
}

enum OwnerTruthMemoryFacetsState: Equatable, Sendable {
    case available(OwnerTruthMemoryFacets)
    case legacyNotAvailable
    case invalid
    case unsupportedSchema(String)

    static func resolve(
        contentSchemaVersion: String,
        content: [String: OwnerTruthJSONValue]
    ) -> OwnerTruthMemoryFacetsState {
        let baseKinds: [OwnerTruthMemoryFacetKind] = [
            .people, .time, .places, .relationships, .emotions, .values, .personality,
        ]
        switch contentSchemaVersion {
        case "owner-truth-v2", "owner-truth-v3":
            guard let rawFacets = content["facets"],
                  let facets = OwnerTruthMemoryFacets(
                    jsonValue: rawFacets,
                    requiredKinds: baseKinds
                  ) else {
                return .invalid
            }
            return .available(facets)
        case "owner-truth-v4", "owner-truth-v5":
            guard let rawFacets = content["facets"],
                  let facets = OwnerTruthMemoryFacets(jsonValue: rawFacets) else {
                return .invalid
            }
            return .available(facets)
        case "owner-truth-v1", "owner-truth-candidate-content-v1":
            return .legacyNotAvailable
        default:
            return .unsupportedSchema(contentSchemaVersion)
        }
    }
}

struct OwnerTruthEvidenceSpan: Codable, Equatable, Sendable {
    let start: Int
    let end: Int

    init?(backendJSONObject value: Any?) {
        guard let object = value as? [String: Any],
              let start = Self.intValue(object["start"]),
              let end = Self.intValue(object["end"]),
              start >= 0,
              end >= start else {
            return nil
        }
        self.start = start
        self.end = end
    }

    private static func intValue(_ value: Any?) -> Int? {
        if let value = value as? Int {
            return value
        }
        if let value = value as? NSNumber,
           CFGetTypeID(value) != CFBooleanGetTypeID(),
           value.doubleValue.rounded() == value.doubleValue {
            return value.intValue
        }
        if let value = value as? String {
            return Int(value)
        }
        return nil
    }
}

struct OwnerTruthCandidateEvidenceReference: Codable, Equatable, Sendable {
    let sourceID: OwnerTruthRecordID
    let sourceVersion: Int
    let span: OwnerTruthEvidenceSpan?

    init(backendJSONObject object: [String: Any]) throws {
        guard let sourceID = Self.recordID(object["sourceId"]),
              let sourceVersion = Self.positiveInt(object["sourceVersion"]) else {
            throw OwnerTruthRemoteContractError.invalidInbox("sourceRefs requires sourceId and positive sourceVersion")
        }
        self.sourceID = sourceID
        self.sourceVersion = sourceVersion
        if object["span"] != nil {
            guard let span = OwnerTruthEvidenceSpan(backendJSONObject: object["span"]) else {
                throw OwnerTruthRemoteContractError.invalidInbox("sourceRefs span is invalid")
            }
            self.span = span
        } else {
            self.span = nil
        }
    }

    fileprivate static func recordID(_ value: Any?) -> OwnerTruthRecordID? {
        guard let rawValue = value as? String,
              let uuid = UUID(uuidString: rawValue.trimmingCharacters(in: .whitespacesAndNewlines)) else {
            return nil
        }
        return OwnerTruthRecordID(rawValue: uuid)
    }

    fileprivate static func requiredString(_ value: Any?) -> String? {
        guard let value = value as? String else { return nil }
        let normalized = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return normalized.isEmpty ? nil : normalized
    }

    fileprivate static func positiveInt(_ value: Any?) -> Int? {
        if let value = value as? Int, value > 0 {
            return value
        }
        if let value = value as? NSNumber,
           CFGetTypeID(value) != CFBooleanGetTypeID(),
           value.doubleValue.rounded() == value.doubleValue,
           value.intValue > 0 {
            return value.intValue
        }
        if let value = value as? String,
           let parsed = Int(value.trimmingCharacters(in: .whitespacesAndNewlines)),
           parsed > 0 {
            return parsed
        }
        return nil
    }

    fileprivate static func nonNegativeInt(_ value: Any?) -> Int? {
        if let value = value as? Int, value >= 0 {
            return value
        }
        if let value = value as? NSNumber,
           CFGetTypeID(value) != CFBooleanGetTypeID(),
           value.doubleValue.rounded() == value.doubleValue,
           value.intValue >= 0 {
            return value.intValue
        }
        if let value = value as? String,
           let parsed = Int(value.trimmingCharacters(in: .whitespacesAndNewlines)),
           parsed >= 0 {
            return parsed
        }
        return nil
    }
}

enum OwnerTruthCandidatePrimaryField: String, Codable, Equatable, Sendable {
    case summary
    case claim
    case label
    case event
    case statement
    case expression

    init(memoryKind: OwnerTruthMemoryKind, contentSchemaVersion: String) {
        let usesTypedField = contentSchemaVersion == "owner-truth-v3"
            || contentSchemaVersion == "owner-truth-v4"
            || contentSchemaVersion == "owner-truth-v5"
        switch memoryKind {
        case .experience:
            self = usesTypedField ? .event : .summary
        case .knowledge:
            self = usesTypedField ? .statement : .claim
        case .emotion:
            self = usesTypedField ? .expression : .label
        }
    }

    var title: String {
        switch self {
        case .summary: return "记忆描述"
        case .claim: return "观点内容"
        case .label: return "感受标签"
        case .event: return "经历内容"
        case .statement: return "知识与经验"
        case .expression: return "感受描述"
        }
    }
}

/// Immutable, Owner-visible preview of the exact ChangeSet the backend will
/// revalidate under a formal-memory revision lock.  This is deliberately a
/// typed transport contract rather than a client-side inference of what a
/// Candidate might do to formal memory.
struct OwnerTruthCandidateChangeSetFieldDiff: Codable, Equatable, Sendable {
    let path: String
    let before: OwnerTruthJSONValue?
    let after: OwnerTruthJSONValue?

    init(backendJSONObject object: [String: Any]) throws {
        guard let path = Self.nonEmptyString(object["path"]) else {
            throw OwnerTruthRemoteContractError.invalidInbox("ChangeSet field diff misses path")
        }
        self.path = path
        before = try Self.optionalJSONValue(object["before"])
        after = try Self.optionalJSONValue(object["after"])
    }

    fileprivate static func optionalJSONValue(_ value: Any?) throws -> OwnerTruthJSONValue? {
        guard let value, !(value is NSNull) else { return nil }
        guard let parsed = OwnerTruthJSONValue(backendJSONObject: value) else {
            throw OwnerTruthRemoteContractError.invalidInbox("ChangeSet field diff contains invalid JSON")
        }
        return parsed
    }

    fileprivate static func nonEmptyString(_ value: Any?) -> String? {
        guard let value = value as? String else { return nil }
        let normalized = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return normalized.isEmpty ? nil : normalized
    }
}

struct OwnerTruthCandidateChangeSetFactDiff: Codable, Equatable, Sendable {
    let before: OwnerTruthJSONValue?
    let after: OwnerTruthJSONValue?
    let candidate: OwnerTruthJSONValue
    let changedFields: [OwnerTruthCandidateChangeSetFieldDiff]
    let beforeEvidenceCount: Int
    let candidateEvidenceCount: Int
    let afterEvidenceCount: Int
    let addedEvidenceCount: Int

    init(backendJSONObject object: [String: Any]) throws {
        before = try OwnerTruthCandidateChangeSetFieldDiff.optionalJSONValue(object["before"])
        after = try OwnerTruthCandidateChangeSetFieldDiff.optionalJSONValue(object["after"])
        guard let rawCandidate = object["candidate"],
              let candidate = OwnerTruthJSONValue(backendJSONObject: rawCandidate),
              let rawChangedFields = object["changedFields"] as? [[String: Any]],
              let evidence = object["evidence"] as? [String: Any],
              let beforeEvidenceCount = Self.nonNegativeInt(evidence["beforeCount"]),
              let candidateEvidenceCount = Self.nonNegativeInt(evidence["candidateCount"]),
              let afterEvidenceCount = Self.nonNegativeInt(evidence["afterCount"]),
              let addedEvidenceCount = Self.nonNegativeInt(evidence["addedCount"]) else {
            throw OwnerTruthRemoteContractError.invalidInbox("ChangeSet fact diff is invalid")
        }
        self.candidate = candidate
        changedFields = try rawChangedFields.map(OwnerTruthCandidateChangeSetFieldDiff.init)
        self.beforeEvidenceCount = beforeEvidenceCount
        self.candidateEvidenceCount = candidateEvidenceCount
        self.afterEvidenceCount = afterEvidenceCount
        self.addedEvidenceCount = addedEvidenceCount
    }

    private static func nonNegativeInt(_ value: Any?) -> Int? {
        if let value = value as? Int, value >= 0 { return value }
        if let value = value as? NSNumber,
           CFGetTypeID(value) != CFBooleanGetTypeID(),
           value.doubleValue.rounded() == value.doubleValue,
           value.intValue >= 0 {
            return value.intValue
        }
        return nil
    }
}

struct OwnerTruthCandidateChangeSetOperation: Codable, Equatable, Sendable, Identifiable {
    let operationIndex: Int
    let operationKind: String
    let targetMemoryID: OwnerTruthRecordID?
    let targetMemoryVersionID: OwnerTruthRecordID?
    let targetMemoryVersion: Int?
    let reason: String
    let changedFields: [String]
    let factDiff: OwnerTruthCandidateChangeSetFactDiff
    let anticipatedActivation: String

    var id: Int { operationIndex }

    init(backendJSONObject object: [String: Any]) throws {
        guard let operationIndex = Self.nonNegativeInt(object["operationIndex"]),
              let operationKind = Self.nonEmptyString(object["operationKind"]),
              let reason = Self.nonEmptyString(object["reason"]),
              let changedFields = object["changedFields"] as? [String],
              let factDiffObject = object["factDiff"] as? [String: Any],
              let anticipatedActivation = Self.nonEmptyString(object["anticipatedActivation"]) else {
            throw OwnerTruthRemoteContractError.invalidInbox("ChangeSet operation is invalid")
        }
        let targetMemoryID = Self.recordID(object["targetMemoryId"])
        let targetMemoryVersionID = Self.recordID(object["targetMemoryVersionId"])
        let targetMemoryVersion = Self.positiveInt(object["targetMemoryVersion"])
        if (targetMemoryID == nil) != (targetMemoryVersionID == nil)
            || (targetMemoryID == nil) != (targetMemoryVersion == nil) {
            throw OwnerTruthRemoteContractError.invalidInbox("ChangeSet target version metadata is incomplete")
        }
        self.operationIndex = operationIndex
        self.operationKind = operationKind
        self.targetMemoryID = targetMemoryID
        self.targetMemoryVersionID = targetMemoryVersionID
        self.targetMemoryVersion = targetMemoryVersion
        self.reason = reason
        self.changedFields = changedFields
        self.factDiff = try OwnerTruthCandidateChangeSetFactDiff(backendJSONObject: factDiffObject)
        self.anticipatedActivation = anticipatedActivation
    }

    private static func recordID(_ value: Any?) -> OwnerTruthRecordID? {
        guard let rawValue = value as? String,
              let uuid = UUID(uuidString: rawValue.trimmingCharacters(in: .whitespacesAndNewlines)) else {
            return nil
        }
        return OwnerTruthRecordID(rawValue: uuid)
    }

    private static func nonEmptyString(_ value: Any?) -> String? {
        guard let value = value as? String else { return nil }
        let normalized = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return normalized.isEmpty ? nil : normalized
    }

    private static func positiveInt(_ value: Any?) -> Int? {
        if let value = value as? Int, value > 0 { return value }
        if let value = value as? NSNumber,
           CFGetTypeID(value) != CFBooleanGetTypeID(),
           value.doubleValue.rounded() == value.doubleValue,
           value.intValue > 0 {
            return value.intValue
        }
        return nil
    }

    private static func nonNegativeInt(_ value: Any?) -> Int? {
        if let value = value as? Int, value >= 0 { return value }
        if let value = value as? NSNumber,
           CFGetTypeID(value) != CFBooleanGetTypeID(),
           value.doubleValue.rounded() == value.doubleValue,
           value.intValue >= 0 {
            return value.intValue
        }
        return nil
    }
}

