struct OwnerTruthFrozenCorrectionInput: Codable, Equatable, Sendable {
    let correctedValueSchemaVersion: String
    let correctedValue: [String: OwnerTruthJSONValue]
}

struct OwnerTruthCandidateCorrectionBinding: Equatable, Sendable {
    static let schemaVersion = "owner-truth-candidate-correction-binding-v1"

    let sourceCandidateVersion: Int
    let sourceCandidateContentHash: String
    let submittedCorrection: OwnerTruthFrozenCorrectionInput
    let resolvedContentHash: String

    init(
        sourceCandidateVersion: Int,
        sourceCandidateContentHash: String,
        submittedCorrection: OwnerTruthFrozenCorrectionInput,
        resolvedContentHash: String
    ) {
        self.sourceCandidateVersion = sourceCandidateVersion
        self.sourceCandidateContentHash = sourceCandidateContentHash
        self.submittedCorrection = submittedCorrection
        self.resolvedContentHash = resolvedContentHash
    }

    init(backendJSONObject object: [String: Any]) throws {
        guard Self.nonEmptyString(object["schemaVersion"]) == Self.schemaVersion else {
            throw OwnerTruthRemoteContractError.invalidInbox("bindingSchemaUnsupported")
        }
        guard let sourceCandidateVersion = Self.positiveInt(object["sourceCandidateVersion"]) else {
            throw OwnerTruthRemoteContractError.invalidInbox("sourceCandidateVersionInvalid")
        }
        guard let sourceCandidateContentHash = Self.sha256(object["sourceCandidateContentHash"]) else {
            throw OwnerTruthRemoteContractError.invalidInbox("sourceCandidateHashInvalid")
        }
        guard let submittedObject = object["submittedCorrection"] as? [String: Any],
              let correctedValueSchemaVersion = Self.nonEmptyString(
                submittedObject["correctedValueSchemaVersion"]
              ),
              let correctedObject = submittedObject["correctedValue"] as? [String: Any],
              let correctedValue = Self.typedObject(correctedObject) else {
            throw OwnerTruthRemoteContractError.invalidInbox("submittedCorrectionInvalid")
        }
        guard let resolvedContentHash = Self.sha256(object["resolvedContentHash"]) else {
            throw OwnerTruthRemoteContractError.invalidInbox("resolvedContentHashInvalid")
        }
        self.sourceCandidateVersion = sourceCandidateVersion
        self.sourceCandidateContentHash = sourceCandidateContentHash
        submittedCorrection = OwnerTruthFrozenCorrectionInput(
            correctedValueSchemaVersion: correctedValueSchemaVersion,
            correctedValue: correctedValue
        )
        self.resolvedContentHash = resolvedContentHash
    }

    private static func typedObject(_ object: [String: Any]) -> [String: OwnerTruthJSONValue]? {
        var result: [String: OwnerTruthJSONValue] = [:]
        result.reserveCapacity(object.count)
        for (key, value) in object {
            guard let typedValue = OwnerTruthJSONValue(backendJSONObject: value) else { return nil }
            result[key] = typedValue
        }
        return result
    }

    private static func nonEmptyString(_ value: Any?) -> String? {
        guard let value = value as? String else { return nil }
        let normalized = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return normalized.isEmpty ? nil : normalized
    }

    private static func sha256(_ value: Any?) -> String? {
        guard let value = nonEmptyString(value),
              value.range(of: "^[0-9a-f]{64}$", options: .regularExpression) != nil else {
            return nil
        }
        return value
    }

    private static func positiveInt(_ value: Any?) -> Int? {
        if let value = value as? Int, value > 0 { return value }
        if let value = value as? NSNumber,
           CFGetTypeID(value) != CFBooleanGetTypeID(),
           value.doubleValue.rounded() == value.doubleValue,
           value.intValue > 0 {
            return value.intValue
        }
        return nil
    }
}

struct OwnerTruthCandidateCorrectionPreviewEnvelope: Equatable, Sendable {
    static let schemaVersion = "owner-truth-candidate-changeset-preview-v1"

    let vaultID: OwnerTruthVaultID
    let candidateID: OwnerTruthRecordID
    let proposal: OwnerTruthCandidateChangeSetProposal
    let correctionBinding: OwnerTruthCandidateCorrectionBinding

    init(
        vaultID: OwnerTruthVaultID,
        candidateID: OwnerTruthRecordID,
        proposal: OwnerTruthCandidateChangeSetProposal,
        correctionBinding: OwnerTruthCandidateCorrectionBinding
    ) {
        self.vaultID = vaultID
        self.candidateID = candidateID
        self.proposal = proposal
        self.correctionBinding = correctionBinding
    }

    init(
        backendJSONObject object: [String: Any],
        expectedVaultID: OwnerTruthVaultID,
        expectedCandidateID: OwnerTruthRecordID
    ) throws {
        guard object["schemaVersion"] as? String == Self.schemaVersion else {
            throw OwnerTruthRemoteContractError.invalidInbox("correctionPreviewEnvelopeInvalid")
        }
        guard object["vaultId"] as? String == expectedVaultID.rawValue else {
            throw OwnerTruthRemoteContractError.invalidInbox("correctionPreviewVaultMismatch")
        }
        guard let rawCandidateID = object["candidateId"] as? String,
              UUID(uuidString: rawCandidateID) == expectedCandidateID.rawValue else {
            throw OwnerTruthRemoteContractError.invalidInbox("correctionPreviewCandidateMismatch")
        }
        guard let proposalObject = object["proposedChangeSet"] as? [String: Any] else {
            throw OwnerTruthRemoteContractError.invalidInbox("correctionPreviewProposalMissing")
        }
        guard let bindingObject = object["correctionBinding"] as? [String: Any] else {
            throw OwnerTruthRemoteContractError.invalidInbox("correctionBindingMissing")
        }
        vaultID = expectedVaultID
        candidateID = expectedCandidateID
        proposal = try OwnerTruthCandidateChangeSetProposal(backendJSONObject: proposalObject)
        correctionBinding = try OwnerTruthCandidateCorrectionBinding(
            backendJSONObject: bindingObject
        )
    }
}

struct OwnerTruthVerifiedCorrectionPreview: Equatable, Sendable {
    let sourceCandidate: OwnerTruthSourceCandidateBinding
    let frozenCorrection: OwnerTruthFrozenCorrectionInput
    let proposal: OwnerTruthCandidateChangeSetProposal
    let traceID: String

    init(
        envelope: OwnerTruthCandidateCorrectionPreviewEnvelope,
        sourceCandidate: OwnerTruthSourceCandidateBinding,
        frozenCorrection: OwnerTruthFrozenCorrectionInput,
        memoryRevision: Int,
        traceID: String
    ) throws {
        guard envelope.vaultID == sourceCandidate.vaultID else {
            throw OwnerTruthRemoteContractError.invalidInbox("correctionPreviewVaultMismatch")
        }
        guard envelope.candidateID == sourceCandidate.candidateID else {
            throw OwnerTruthRemoteContractError.invalidInbox("correctionPreviewCandidateMismatch")
        }
        guard envelope.correctionBinding.sourceCandidateVersion == sourceCandidate.candidateVersion else {
            throw OwnerTruthRemoteContractError.invalidInbox("sourceCandidateVersionMismatch")
        }
        guard envelope.correctionBinding.sourceCandidateContentHash == sourceCandidate.candidateContentHash else {
            throw OwnerTruthRemoteContractError.invalidInbox("sourceCandidateHashMismatch")
        }
        guard envelope.proposal.candidateVersion == sourceCandidate.candidateVersion else {
            throw OwnerTruthRemoteContractError.invalidInbox("proposalCandidateVersionMismatch")
        }
        guard envelope.correctionBinding.submittedCorrection == frozenCorrection else {
            throw OwnerTruthRemoteContractError.invalidInbox("submittedCorrectionMismatch")
        }
        guard envelope.correctionBinding.resolvedContentHash == envelope.proposal.candidateContentHash else {
            throw OwnerTruthRemoteContractError.invalidInbox("resolvedContentHashMismatch")
        }
        guard envelope.proposal.baseMemoryRevision == memoryRevision else {
            throw OwnerTruthRemoteContractError.invalidInbox("memoryRevisionMismatch")
        }
        guard envelope.proposal.reviewability == .reviewable else {
            throw OwnerTruthRemoteContractError.invalidInbox("correctionPreviewNotReviewable")
        }
        self.sourceCandidate = sourceCandidate
        self.frozenCorrection = frozenCorrection
        proposal = envelope.proposal
        self.traceID = traceID
    }

    func matches(candidate: OwnerTruthCandidateInboxItem, memoryRevision: Int?) -> Bool {
        sourceCandidate.vaultID == candidate.vaultID
            && sourceCandidate.candidateID == candidate.id
            && sourceCandidate.candidateVersion == candidate.candidateVersion
            && sourceCandidate.candidateContentHash == candidate.contentHash
            && proposal.candidateVersion == candidate.candidateVersion
            && proposal.baseMemoryRevision == memoryRevision
            && proposal.reviewability == .reviewable
    }
}

extension OwnerTruthCandidateChangeSetProposal {
    var reviewability: OwnerTruthCandidateChangeSetReviewability {
        operations.allSatisfy { $0.reviewability == .reviewable }
            ? .reviewable
            : .incomplete
    }
}

struct OwnerTruthCandidateInboxItem: Codable, Equatable, Sendable, Identifiable {
    let id: OwnerTruthRecordID
    let vaultID: OwnerTruthVaultID
    let sourceID: OwnerTruthRecordID
    let memoryKind: OwnerTruthMemoryKind
    let perspective: OwnerTruthPerspectiveType
    let epistemicStatus: OwnerTruthEpistemicStatus
    let sensitivity: OwnerTruthSensitivityLevel
    let contentSchemaVersion: String
    let content: [String: OwnerTruthJSONValue]
    let contentHash: String
    let sourceReferences: [OwnerTruthCandidateEvidenceReference]
    let reviewMode: String
    let candidateVersion: Int
    let proposedChangeSet: OwnerTruthCandidateChangeSetProposal?
    let createdAt: Date?

    init(backendJSONObject object: [String: Any], vaultID: OwnerTruthVaultID) throws {
        guard let id = OwnerTruthCandidateEvidenceReference.recordID(object["candidateId"]),
              let sourceID = OwnerTruthCandidateEvidenceReference.recordID(object["sourceId"]),
              let memoryKind = Self.enumValue(OwnerTruthMemoryKind.self, object["memoryKind"]),
              let perspective = Self.enumValue(OwnerTruthPerspectiveType.self, object["perspectiveType"]),
              let epistemicStatus = Self.enumValue(OwnerTruthEpistemicStatus.self, object["epistemicStatus"]),
              let sensitivity = Self.enumValue(OwnerTruthSensitivityLevel.self, object["sensitivity"]),
              let contentSchemaVersion = Self.nonEmptyString(object["contentSchemaVersion"]),
              let contentObject = object["content"] as? [String: Any],
              !contentObject.isEmpty,
              let contentHash = Self.nonEmptyString(object["contentHash"]),
              let sourceReferenceObjects = object["sourceRefs"] as? [[String: Any]],
              !sourceReferenceObjects.isEmpty,
              let reviewMode = Self.nonEmptyString(object["reviewMode"]),
              let candidateVersion = OwnerTruthCandidateEvidenceReference.positiveInt(object["candidateVersion"]) else {
            throw OwnerTruthRemoteContractError.invalidInbox("candidate item misses a required typed field")
        }

        var content: [String: OwnerTruthJSONValue] = [:]
        content.reserveCapacity(contentObject.count)
        for (key, value) in contentObject {
            guard let parsed = OwnerTruthJSONValue(backendJSONObject: value) else {
                throw OwnerTruthRemoteContractError.invalidInbox("candidate content contains an unsupported JSON value")
            }
            content[key] = parsed
        }

        let primaryField = OwnerTruthCandidatePrimaryField(
            memoryKind: memoryKind,
            contentSchemaVersion: contentSchemaVersion
        )
        guard case .string(let rawPrimaryValue)? = content[primaryField.rawValue],
              !rawPrimaryValue.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            throw OwnerTruthRemoteContractError.invalidInbox(
                "candidate content misses the required \(primaryField.rawValue) field"
            )
        }

        let sourceReferences = try sourceReferenceObjects.map(OwnerTruthCandidateEvidenceReference.init(backendJSONObject:))
        guard sourceReferences.contains(where: { $0.sourceID == sourceID }) else {
            throw OwnerTruthRemoteContractError.invalidInbox("candidate sourceId is absent from sourceRefs")
        }

        self.id = id
        self.vaultID = vaultID
        self.sourceID = sourceID
        self.memoryKind = memoryKind
        self.perspective = perspective
        self.epistemicStatus = epistemicStatus
        self.sensitivity = sensitivity
        self.contentSchemaVersion = contentSchemaVersion
        self.content = content
        self.contentHash = contentHash
        self.sourceReferences = sourceReferences
        self.reviewMode = reviewMode
        self.candidateVersion = candidateVersion
        if let proposalObject = object["proposedChangeSet"] as? [String: Any] {
            let proposal = try OwnerTruthCandidateChangeSetProposal(backendJSONObject: proposalObject)
            guard proposal.candidateVersion == candidateVersion,
                  proposal.candidateContentHash == contentHash else {
                throw OwnerTruthRemoteContractError.invalidInbox(
                    "ChangeSet proposal does not bind the displayed Candidate"
                )
            }
            proposedChangeSet = proposal
        } else if contentSchemaVersion == "owner-truth-v5" {
            // V5 writes must fail closed in the use case. Keep the Candidate
            // visible so the owner can refresh, but never synthesize a diff.
            proposedChangeSet = nil
        } else {
            proposedChangeSet = nil
        }
        self.createdAt = try Self.date(object["createdAt"])
    }

    var primaryField: OwnerTruthCandidatePrimaryField {
        OwnerTruthCandidatePrimaryField(
            memoryKind: memoryKind,
            contentSchemaVersion: contentSchemaVersion
        )
    }

    var facetsState: OwnerTruthMemoryFacetsState {
        OwnerTruthMemoryFacetsState.resolve(
            contentSchemaVersion: contentSchemaVersion,
            content: content
        )
    }

    var primaryValue: String {
        guard case .string(let rawValue)? = content[primaryField.rawValue] else {
            return ""
        }
        return rawValue.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private static func nonEmptyString(_ value: Any?) -> String? {
        guard let value = value as? String else { return nil }
        let normalized = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return normalized.isEmpty ? nil : normalized
    }

    private static func enumValue<Value: RawRepresentable>(
        _ type: Value.Type,
        _ value: Any?
    ) -> Value? where Value.RawValue == String {
        guard let rawValue = nonEmptyString(value) else { return nil }
        return Value(rawValue: rawValue)
    }

    private static func date(_ value: Any?) throws -> Date? {
        guard let value else { return nil }
        if value is NSNull { return nil }
        guard let rawValue = nonEmptyString(value) else {
            throw OwnerTruthRemoteContractError.invalidInbox("createdAt must be an ISO-8601 value or null")
        }
        let fractionalFormatter = ISO8601DateFormatter()
        fractionalFormatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
        let standardFormatter = ISO8601DateFormatter()
        guard let date = fractionalFormatter.date(from: rawValue)
            ?? standardFormatter.date(from: rawValue) else {
            throw OwnerTruthRemoteContractError.invalidInbox("createdAt is not valid ISO-8601")
        }
        return date
    }
}

struct OwnerTruthCandidateInbox: Codable, Equatable, Sendable {
    static let schemaVersion = "owner-truth-candidate-inbox-v1"

    let vaultID: OwnerTruthVaultID
    let candidates: [OwnerTruthCandidateInboxItem]
    /// Optional during the additive server rollout. When present it is sent
    /// back on a review write so the server can reject a stale formal-memory
    /// snapshot instead of silently applying an unrelated change.
    let memoryRevision: Int?

    init(backendJSONObject object: [String: Any], expectedVaultID: OwnerTruthVaultID) throws {
        guard Self.nonEmptyString(object["schemaVersion"]) == Self.schemaVersion,
              let responseVaultID = Self.nonEmptyString(object["vaultId"]),
              responseVaultID == expectedVaultID.rawValue,
              let candidateObjects = object["candidates"] as? [[String: Any]] else {
            throw OwnerTruthRemoteContractError.invalidInbox("schemaVersion, vaultId or candidates does not match the contract")
        }
        vaultID = expectedVaultID
        candidates = try candidateObjects.map {
            try OwnerTruthCandidateInboxItem(backendJSONObject: $0, vaultID: expectedVaultID)
        }
        if let rawRevision = object["memoryRevision"], !(rawRevision is NSNull) {
            guard let revision = rawRevision as? Int, revision >= 0 else {
                throw OwnerTruthRemoteContractError.invalidInbox(
                    "memoryRevision must be a non-negative integer or null"
                )
            }
            memoryRevision = revision
        } else {
            memoryRevision = nil
        }
    }

    private static func nonEmptyString(_ value: Any?) -> String? {
        guard let value = value as? String else { return nil }
        let normalized = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return normalized.isEmpty ? nil : normalized
    }
}

enum OwnerTruthCandidateMemoryActivationStatus: String, Codable, Equatable, Sendable {
    case current
    case superseded
    case deduplicated
    case pending
    case notApplicable
}

struct OwnerTruthCandidateReviewHistoryMemoryActivation: Codable, Equatable, Sendable {
    let status: OwnerTruthCandidateMemoryActivationStatus
    let memoryID: OwnerTruthRecordID?
    let memoryVersionID: OwnerTruthRecordID?
    let memoryVersion: Int?

    init(backendJSONObject object: [String: Any]) throws {
        guard let rawStatus = Self.nonEmptyString(object["status"]),
              let status = OwnerTruthCandidateMemoryActivationStatus(rawValue: rawStatus) else {
            throw OwnerTruthRemoteContractError.invalidInbox(
                "review history memoryActivation.status is invalid"
            )
        }
        let memoryID = try Self.optionalRecordID(object["memoryId"], field: "memoryId")
        let memoryVersionID = try Self.optionalRecordID(
            object["memoryVersionId"],
            field: "memoryVersionId"
        )
        let memoryVersion: Int?
        if object["memoryVersion"] == nil || object["memoryVersion"] is NSNull {
            memoryVersion = nil
        } else {
            guard let parsed = OwnerTruthCandidateEvidenceReference.positiveInt(
                object["memoryVersion"]
            ) else {
                throw OwnerTruthRemoteContractError.invalidInbox(
                    "review history memoryVersion must be positive or null"
                )
            }
            memoryVersion = parsed
        }
        switch status {
        case .current, .superseded:
            guard memoryID != nil, memoryVersionID != nil, memoryVersion != nil else {
                throw OwnerTruthRemoteContractError.invalidInbox(
                    "current or superseded review history requires a MemoryVersion"
                )
            }
        case .deduplicated:
            let suppliedValues = [memoryID != nil, memoryVersionID != nil, memoryVersion != nil]
            guard suppliedValues.allSatisfy({ $0 }) || suppliedValues.allSatisfy({ !$0 }) else {
                throw OwnerTruthRemoteContractError.invalidInbox(
                    "deduplicated review history must include a complete MemoryVersion or none"
                )
            }
        case .pending, .notApplicable:
            guard memoryID == nil, memoryVersionID == nil, memoryVersion == nil else {
                throw OwnerTruthRemoteContractError.invalidInbox(
                    "pending or notApplicable review history cannot claim a MemoryVersion"
                )
            }
        }
        self.status = status
        self.memoryID = memoryID
        self.memoryVersionID = memoryVersionID
        self.memoryVersion = memoryVersion
    }

    private static func optionalRecordID(
        _ value: Any?,
        field: String
    ) throws -> OwnerTruthRecordID? {
        guard let value, !(value is NSNull) else { return nil }
        guard let parsed = OwnerTruthCandidateEvidenceReference.recordID(value) else {
            throw OwnerTruthRemoteContractError.invalidInbox(
                "review history \(field) must be a UUID or null"
            )
        }
        return parsed
    }

    private static func nonEmptyString(_ value: Any?) -> String? {
        guard let value = value as? String else { return nil }
        let normalized = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return normalized.isEmpty ? nil : normalized
    }
}

struct OwnerTruthCandidateReviewHistoryItem: Codable, Equatable, Sendable, Identifiable {
    let candidate: OwnerTruthCandidateInboxItem
    let decision: OwnerTruthCandidateDecision
    let decidedAt: Date
    let memoryActivation: OwnerTruthCandidateReviewHistoryMemoryActivation

    var id: OwnerTruthRecordID { candidate.id }

    init(backendJSONObject object: [String: Any], vaultID: OwnerTruthVaultID) throws {
        guard let candidateObject = object["candidate"] as? [String: Any],
              let rawDecision = Self.nonEmptyString(object["decision"]),
              let decision = OwnerTruthCandidateDecision(rawValue: rawDecision),
              decision.isTerminal,
              let rawDecidedAt = Self.nonEmptyString(object["decidedAt"]),
              let decidedAt = Self.date(rawDecidedAt),
              let activationObject = object["memoryActivation"] as? [String: Any] else {
            throw OwnerTruthRemoteContractError.invalidInbox(
                "review history item misses a required typed field"
            )
        }
        let candidate = try OwnerTruthCandidateInboxItem(
            backendJSONObject: candidateObject,
            vaultID: vaultID
        )
        let activation = try OwnerTruthCandidateReviewHistoryMemoryActivation(
            backendJSONObject: activationObject
        )
        switch decision {
        case .accepted, .corrected:
            guard activation.status != .pending else {
                throw OwnerTruthRemoteContractError.invalidInbox(
                    "accepted or corrected review cannot remain pending"
                )
            }
        case .rejected, .invalidated:
            guard activation.status == .notApplicable else {
                throw OwnerTruthRemoteContractError.invalidInbox(
                    "rejected or invalidated review cannot activate memory"
                )
            }
        case .pending:
            throw OwnerTruthRemoteContractError.invalidInbox(
                "pending is not a review history decision"
            )
        }
        self.candidate = candidate
        self.decision = decision
        self.decidedAt = decidedAt
        self.memoryActivation = activation
    }

    private static func nonEmptyString(_ value: Any?) -> String? {
        guard let value = value as? String else { return nil }
        let normalized = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return normalized.isEmpty ? nil : normalized
    }

    private static func date(_ value: String) -> Date? {
        let fractionalFormatter = ISO8601DateFormatter()
        fractionalFormatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
        let standardFormatter = ISO8601DateFormatter()
        return fractionalFormatter.date(from: value) ?? standardFormatter.date(from: value)
    }
}

struct OwnerTruthCandidateReviewHistory: Codable, Equatable, Sendable {
    static let schemaVersion = "owner-truth-candidate-review-history-v1"

    let vaultID: OwnerTruthVaultID
